#include <stdint.h>
#include <string.h>
#include "stm32f407xx.h"

volatile uint32_t tick = 0;

volatile uint32_t dma_done = 1;

// SysTick 中斷 handler（每 1ms 觸發一次）
void SysTick_Handler(void)
{
    tick++;
}

void delay_ms(uint32_t ms)
{
    uint32_t start = tick;
    while ((tick - start) < ms);
}

void DMA2_Stream7_IRQHandler(void) {
	if (DMA2 -> HISR & (1 << 27)) {
		DMA2 -> HIFCR |= (1 << 27); // set 1 to clear interrupt register
		dma_done = 1;
	}
}

void uart_dma_send(const char *str) {
	uint16_t len = strlen(str);

	while (!dma_done) {};
	dma_done = 0;
	DMA2_Stream7 -> CR &= ~(1 << 0);
	while (DMA2_Stream7 -> CR & ( 1 << 0));

	DMA2 -> HIFCR |= (0x3F << 22); // clear stream7 flag

	DMA2_Stream7 -> NDTR = len;
	DMA2_Stream7 -> PAR = (uint32_t)&(USART1 -> DR);
	DMA2_Stream7 -> M0AR  = (uint32_t)str;

	DMA2_Stream7 -> CR = (4 << 25)    // Channel 4 (USART1_TX)
                       | (1 << 6)     // DIR = memory → peripheral
                       | (1 << 10)    // MINC = memory 地址遞增
                       | (1 << 4)     // TCIE = Transfer Complete 中斷
                       | (1 << 0);    // EN = 啟動
}

int main(void)
{
	// 1. 設定 SysTick 每 1ms 中斷一次
	// 系統預設 clock = 16MHz
	// 16000000 / 1000 = 16000 counts per ms
	SYSTICK -> LOAD = 16000 - 1;   	// reload value
	SYSTICK -> VAL  = 0;            // 清除目前值
	SYSTICK -> CTRL = 0x7;			// bit0=enable, bit1=tickint, bit2=clksource(內部clock)

	RCC -> AHB1ENR |= RCC_AHB1ENR_GPIOAEN;
	RCC -> AHB1ENR |= RCC_AHB1ENR_DMA2EN;
	RCC -> APB2ENR |= RCC_APB2ENR_USART1EN;

	GPIOA -> MODER &= ~(0x3 << (9 * 2));
	GPIOA -> MODER |=  (GPIO_MODER_AF << (9 * 2));
	GPIOA -> MODER &= ~(0x3 << (10 * 2));
	GPIOA -> MODER |=  (GPIO_MODER_AF << (10 * 2));
	GPIOA -> AFRH  &= ~(0xF << ((9-8) * 4));
	GPIOA -> AFRH  |=  (0x7 << ((9-8) * 4));
	GPIOA -> AFRH  &= ~(0xF << ((10-8) * 4));
	GPIOA -> AFRH  |=  (0x7 << ((10-8) * 4));

	USART1 -> CR1 = 0;
	USART1 -> BRR = 833;                     // 16MHz / 1200 0x3415
	USART1 -> CR3 = (1 << 7);
	USART1 -> CR1 = (1 << 13) | (1 << 3);

	NVIC -> ISER[2] = (1 << 6);

	uart_dma_send("DMA+UART ready!\r\n");

	uint32_t count = 0;
	char buf[32];

	while (1)
	{
		// 簡單計數器，證明 CPU 沒被 UART 卡住
		count++;

		// 用 sprintf 的話要 #include <stdio.h>，這裡手動拼
		buf[0] = 'c'; buf[1] = 'n'; buf[2] = 't';
		buf[3] = '=';
		buf[4] = '0' + (count / 100) % 10;
		buf[5] = '0' + (count / 10) % 10;
		buf[6] = '0' + count % 10;
		buf[7] = '\r'; buf[8] = '\n'; buf[9] = '\0';

		uart_dma_send(buf);
		delay_ms(500);
	}
}
